typedef unsigned int size_t;

void *operator new(size_t, unsigned int, const char *, int);
#define NEW new(0, __FILE__, __LINE__)

class camera;
class Menu;
class MenuSystem;

class MenuEntry {
  unsigned int flags;

public:
  MenuEntry() { flags = 3; }
  virtual ~MenuEntry();
  virtual void OnMenuOpen(Menu *, MenuSystem *);
  virtual void OnMenuClose();
  virtual void OnButtonPress(int);
};

class MenuEntryLabel : public MenuEntry {
protected:
  const char *label;

public:
  MenuEntryLabel(const char *t) { label = t; }
  virtual ~MenuEntryLabel();
};

class Menu {
public:
  Menu(Menu *);
  void AddEntry(MenuEntry *);
};

class Submenu : public MenuEntryLabel {
  Menu *menuopen;
  Menu *parent;
  MenuSystem *system;

public:
  Submenu(char *text, Menu *p) : MenuEntryLabel(text) {
    menuopen = p;
    parent = 0;
    system = 0;
  }
  virtual ~Submenu();
  virtual void OnButtonPress(int);
  virtual void OnMenuOpen(Menu *, MenuSystem *);
  virtual void OnMenuClose();
};

class camMenuObj {
public:
  camMenuObj(char *, Menu *, camera *);
  ~camMenuObj();

  bool deleted;
  bool po_changed;

private:
  camera *p_dbg_cam;
  void *cam_title;
  void *ent1;
  void *ent2;
  Menu *inner_menu;
  Submenu *cam_submenu;
  Menu *parent;
};

template <class T> class Node {
public:
  T *Obj;
  Node<T> *next;
  Node<T> *prev;

  Node() {
    Obj = 0;
    next = prev = 0;
  }
};

template <class T> class List {
  Node<T> *head;
  Node<T> *tail;

public:
  void AddBack(T *Obj) {
    Node<T> *node = NEW Node<T>();
    node->Obj = Obj;
    node->next = tail;
    node->prev = tail->prev;
    tail->prev->next = node;
    tail->prev = node;
  }
};

class camera_list {
public:
  char *GetName(int n) { return names[n]; }
  int GetNumCams(void) { return num_cams; }

  Submenu *smenu;
  Menu *cam_menu;
  camera **camlist_start;
  List<camMenuObj> dbmenu_list;

private:
  int num_cams;
  char **names;
};

extern camera_list *CameraList;
extern Menu *menu_inner_camtool;

void CreateDebugMenuTools(void)
{
	for (int cams = 0; cams < CameraList->GetNumCams(); cams++)
	{
		if (CameraList->smenu == NULL)
		{
			CameraList->cam_menu = NEW Menu(menu_inner_camtool);
			CameraList->smenu = NEW Submenu("Edit Cameras", CameraList->cam_menu);
			menu_inner_camtool->AddEntry(CameraList->smenu);
		}

		camMenuObj *Obj = NEW camMenuObj(CameraList->GetName(cams), CameraList->cam_menu, CameraList->camlist_start[cams]);
		CameraList->dbmenu_list.AddBack(Obj);
	}
}
